CREATE TABLE IF NOT EXISTS balance_heroes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),external_id text,slug text NOT NULL UNIQUE,name_en text NOT NULL,name_ru text NOT NULL,short_name text,primary_attribute text NOT NULL CHECK(primary_attribute IN('strength','agility','intelligence','universal')),attack_type text NOT NULL CHECK(attack_type IN('melee','ranged')),roles text[] NOT NULL DEFAULT '{}',tags text[] NOT NULL DEFAULT '{}',portrait_url text,icon_url text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled','hidden','archived')),sort_order integer NOT NULL DEFAULT 0,current_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),created_by text NOT NULL,updated_by text NOT NULL,row_version integer NOT NULL DEFAULT 1 CHECK(row_version>0));
CREATE INDEX IF NOT EXISTS balance_heroes_status_sort_idx ON balance_heroes(status,sort_order);
CREATE TABLE IF NOT EXISTS balance_abilities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hero_id uuid NOT NULL REFERENCES balance_heroes(id),slug text NOT NULL,name_en text NOT NULL,name_ru text NOT NULL,description_en text NOT NULL,description_ru text NOT NULL,type text NOT NULL CHECK(type IN('basic','ultimate','innate')),slot integer NOT NULL,max_level integer NOT NULL CHECK(max_level>0),behavior text[] NOT NULL DEFAULT '{}',damage_type text NOT NULL,target_type text[] NOT NULL DEFAULT '{}',dispel_type text,pierces_debuff_immunity boolean NOT NULL DEFAULT false,icon_url text,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled','hidden','archived')),ability_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),row_version integer NOT NULL DEFAULT 1,UNIQUE(hero_id,slug));
CREATE UNIQUE INDEX IF NOT EXISTS balance_ability_active_slot_uidx ON balance_abilities(hero_id,slot) WHERE status<>'archived';
CREATE TABLE IF NOT EXISTS balance_facets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hero_id uuid NOT NULL REFERENCES balance_heroes(id),slug text NOT NULL,name_en text NOT NULL,name_ru text NOT NULL,description_en text NOT NULL,description_ru text NOT NULL,facet_data jsonb NOT NULL,status text NOT NULL DEFAULT 'active',sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(hero_id,slug));
CREATE TABLE IF NOT EXISTS balance_talents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hero_id uuid NOT NULL REFERENCES balance_heroes(id),tier integer NOT NULL CHECK(tier IN(10,15,20,25)),side text NOT NULL CHECK(side IN('left','right')),name_en text NOT NULL,name_ru text NOT NULL,description_en text NOT NULL,description_ru text NOT NULL,talent_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(hero_id,tier,side));
CREATE TABLE IF NOT EXISTS balance_upgrades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),hero_id uuid NOT NULL REFERENCES balance_heroes(id),ability_id uuid REFERENCES balance_abilities(id),type text NOT NULL CHECK(type IN('scepter','shard')),name_en text NOT NULL,name_ru text NOT NULL,description_en text NOT NULL,description_ru text NOT NULL,upgrade_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS balance_patches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,version text NOT NULL UNIQUE,title_en text NOT NULL,title_ru text NOT NULL,summary_en text NOT NULL,summary_ru text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','in_review','approved','scheduled','published','superseded','archived')),release_channel text NOT NULL DEFAULT 'test' CHECK(release_channel IN('test','production')),scheduled_at timestamptz,published_at timestamptz,supersedes_patch_id uuid REFERENCES balance_patches(id),rollback_of_patch_id uuid REFERENCES balance_patches(id),created_by text NOT NULL,reviewed_by text,approved_by text,published_by text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),row_version integer NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS balance_patches_public_idx ON balance_patches(release_channel,status,published_at DESC);
CREATE TABLE IF NOT EXISTS balance_patch_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patch_id uuid NOT NULL REFERENCES balance_patches(id),entity_type text NOT NULL CHECK(entity_type IN('hero','ability','facet','talent','upgrade','system')),entity_id uuid,operation text NOT NULL CHECK(operation IN('create','update','archive','restore')),before_data jsonb,after_data jsonb,category text NOT NULL,title_en text NOT NULL,title_ru text NOT NULL,description_en text NOT NULL,description_ru text NOT NULL,sort_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS balance_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patch_id uuid NOT NULL REFERENCES balance_patches(id),entity_type text NOT NULL,entity_id uuid NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(patch_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS balance_import_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),status text NOT NULL,schema_version text NOT NULL,dry_run boolean NOT NULL,payload_hash text NOT NULL,total_rows integer NOT NULL,valid_rows integer NOT NULL,invalid_rows integer NOT NULL,errors jsonb NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX IF NOT EXISTS balance_import_hash_idx ON balance_import_jobs(payload_hash,status);
ALTER TABLE matches ADD COLUMN IF NOT EXISTS balance_patch_id uuid REFERENCES balance_patches(id);
ALTER TABLE matches ADD COLUMN IF NOT EXISTS balance_patch_version text;
CREATE OR REPLACE FUNCTION protect_published_balance_entry() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM balance_patches WHERE id=OLD.patch_id AND status IN('published','superseded')) THEN RAISE EXCEPTION 'published balance entries are immutable'; END IF; RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END $$;
DROP TRIGGER IF EXISTS balance_entry_immutable ON balance_patch_entries;
CREATE TRIGGER balance_entry_immutable BEFORE UPDATE OR DELETE ON balance_patch_entries FOR EACH ROW EXECUTE FUNCTION protect_published_balance_entry();
